/**
 * The 20 Premier League clubs — the reference data behind every ClubBadge, club
 * tab and club picker in the app.
 *
 * `primaryColor` is the club's well-known kit colour, used only to tint the
 * generated placeholder crest. Real crests are trademarked (§13); `public/crests/`
 * holds neutral initials-on-colour SVGs generated by `scripts/generate-crests.mjs`.
 * Swapping in licensed artwork later is a one-file change here.
 */

export type ClubId =
  | 'arsenal'
  | 'aston-villa'
  | 'bournemouth'
  | 'brentford'
  | 'brighton'
  | 'chelsea'
  | 'crystal-palace'
  | 'everton'
  | 'fulham'
  | 'ipswich'
  | 'leicester'
  | 'liverpool'
  | 'man-city'
  | 'man-utd'
  | 'newcastle'
  | 'nottingham-forest'
  | 'southampton'
  | 'tottenham'
  | 'west-ham'
  | 'wolves'

export interface Club {
  id: ClubId
  /** Full name, rendered verbatim — never snake_cased (§3.3b guardrail 1). */
  name: string
  /** Short form for dense table cells and club tabs. */
  short: string
  stadium: string
  city: string
  primaryColor: string
  crest: string
}

function club(
  id: ClubId,
  name: string,
  short: string,
  stadium: string,
  city: string,
  primaryColor: string,
): Club {
  return { id, name, short, stadium, city, primaryColor, crest: `/crests/${id}.svg` }
}

