const BY_ID = new Map(CLUBS.map((c) => [c.id, c]))

export function getClub(id: ClubId): Club {
  const found = BY_ID.get(id)
  if (!found) throw new Error(`Unknown club: ${id}`)
  return found
}

/** Two-letter mark for the generated crest and for avatar fallbacks. */
export function clubInitials(club: Club): string {
  const words = club.short.split(/\s+/)
  if (words.length > 1) return (words[0]![0]! + words[1]![0]!).toUpperCase()
  return club.short.slice(0, 2).toUpperCase()
}
